        var brandRow=new StackPanel{Orientation=Orientation.Horizontal};var mark=new Border{Width=35,Height=35,CornerRadius=new CornerRadius(10),Background=B("#40331F"),Margin=new Thickness(0,0,10,0)};mark.Child=AppIdentity.Mark();brandRow.Children.Add(mark);brand=T("Mon espace",17);brand.FontWeight=FontWeights.SemiBold;brand.VerticalAlignment=VerticalAlignment.Center;brandRow.Children.Add(brand);sideGrid.Children.Add(brandRow);
