    string ResourcesText(){return AppearanceStyles();}
    Brush Accent{get{return (Brush)FindResource("Accent");}}
    internal static Brush B(string hex){return (Brush)new BrushConverter().ConvertFromString(hex);}
    TextBlock T(string text,double size=13,Brush brush=null,Thickness? margin=null){return new TextBlock{Text=text??"",FontSize=size,Foreground=brush==Accent?AccentText:brush??Ink,TextWrapping=TextWrapping.Wrap,Margin=margin??new Thickness(0)};}
    WButton Btn(string text,Action click,bool primary=false,bool quiet=false){var b=new WButton{Content=text,Margin=new Thickness(0,0,7,0),Tag=primary?"primary":"normal",Background=primary?Accent:quiet?Brushes.Transparent:SurfaceBrush,Foreground=primary?new SolidColorBrush(Appearance.TextOn(CurrentPalette.Accent)):Ink};b.Click+=delegate{click();};return b;}
    Border Box(UIElement child,Thickness? padding=null){return new Border{Background=CardBg,CornerRadius=new CornerRadius(16),BorderBrush=FaintLine,BorderThickness=new Thickness(1),Padding=padding??new Thickness(22),Child=child};}
    Border Card(string title,UIElement body,Action all=null){var stack=new StackPanel();var heading=new DockPanel{Margin=new Thickness(0,0,0,16)};if(all!=null){var link=Btn("Tout voir ↗",all,false,true);DockPanel.SetDock(link,Dock.Right);heading.Children.Add(link);}var caption=T(title,17);caption.FontWeight=FontWeights.SemiBold;heading.Children.Add(caption);stack.Children.Add(heading);stack.Children.Add(body);var card=Box(stack);card.Tag="card:"+title;return card;}
    void Go(string page){openProject="";selected=page;Refresh();}
    internal void Refresh(){if(!FlushDeskNotes())return;if(RenderPrivacy())return;ApplyAppearance();UpdateMiniPlayer();brand.Text=store.Value.settings.AppTitle;profile.Text=String.IsNullOrWhiteSpace(store.Value.settings.DisplayName)?"Votre espace":store.Value.settings.DisplayName;crumb.Text=store.Value.settings.AppTitle+"  /  "+selected;RebuildNavigation();UpdateWorkspaceTabs();var wrapper=new StackPanel();PageHeaderV3(wrapper);UndoBanner(wrapper);if((googleBusy||!String.IsNullOrEmpty(googleMessage))&&selected!="Google Drive"&&selected!="Agenda"){var googleStatus=new DockPanel{Margin=new Thickness(0,0,0,14)};var dismiss=Btn(googleBusy?"Annuler":"×",delegate{if(googleBusy)CancelGoogle();else{googleMessage="";Refresh();}},false,true);DockPanel.SetDock(dismiss,Dock.Right);googleStatus.Children.Add(dismiss);googleStatus.Children.Add(T(googleMessage,11,Muted));wrapper.Children.Add(googleStatus);}
        if(selected=="Documents locaux")LocalDocumentsPage(wrapper);else if(selected=="Mises à jour")UpdatesPage(wrapper);else if(selected=="Boîte de réception")InboxPage(wrapper);else if(selected=="Habitudes")HabitsPage(wrapper);else if(selected=="Bilan de la semaine")WeekReviewPage(wrapper);else if(selected=="Recherche")SearchPage(wrapper);else if(selected=="Favoris")FavoritesPage(wrapper);else if(selected=="Aujourd’hui")Home(wrapper);else if(selected=="Concentration")FocusPage(wrapper);else if(selected=="Mes tâches")Tasks(wrapper);else if(selected=="Modèles de projets")TemplatesPage(wrapper);else if(selected=="Mes projets"){if(String.IsNullOrEmpty(openProject))Projects(wrapper);else ProjectDetails(wrapper);}else if(selected=="Mes notes")Notes(wrapper);else if(selected=="Suppressions récentes")DeletedPage(wrapper);else if(selected=="Mes modes")ModesPage(wrapper);else if(selected=="Mon épargne")SavingsPage(wrapper);else if(selected=="Bilan budget")BudgetReportPage(wrapper);else if(selected=="Rappels budget")BudgetReminderPage(wrapper);else if(selected=="Mon budget")BudgetPage(wrapper);else if(selected=="Ma musique")MusicPage(wrapper);else if(selected=="Agenda")Agenda(wrapper);else if(selected=="Rappels")RemindersPage(wrapper);else if(selected=="Google Drive")GooglePage(wrapper);else if(selected=="Mes services")Services(wrapper);else Preferences(wrapper);content.Content=WorkspaceView(wrapper);}
    void Home(StackPanel root){HomeV2(root);}

    StackPanel TaskList(IEnumerable<WorkTask> source,int limit){var list=new StackPanel();var tasks=(limit>0?source.Take(limit):source).ToList();if(tasks.Count==0){list.Children.Add(T("Tout est clair pour le moment.",12,Muted,new Thickness(0,6,0,8)));list.Children.Add(T("Ajoutez une tâche pour préparer la suite.",11,Muted,new Thickness(0,0,0,15)));list.Children.Add(Btn("+  Ajouter une tâche",delegate{owner.Edit(null);},false,true));return list;}foreach(var task in tasks){var row=new Grid{Margin=new Thickness(0,0,0,1)};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(27)});row.ColumnDefinitions.Add(new ColumnDefinition());var check=new CheckBox{IsChecked=task.status=="done",VerticalAlignment=VerticalAlignment.Top,Margin=new Thickness(0,14,0,0)};check.Click+=delegate{if(check.IsChecked==true)Schedule.Complete(store.Value,task);else task.status="todo";owner.Save();Refresh();};row.Children.Add(check);var text=new StackPanel{Margin=new Thickness(0,6,0,14)};Grid.SetColumn(text,1);var edit=Btn(task.title,delegate{owner.Edit(task);},false,true);edit.Padding=new Thickness(0,4,0,4);edit.HorizontalContentAlignment=HorizontalAlignment.Left;edit.Content=new TextBlock{Text=task.title,TextWrapping=TextWrapping.Wrap,Foreground=task.status=="done"?Muted:Ink,FontSize=14};PinMenu(edit,"task",task.id,task.title);text.Children.Add(edit);text.Children.Add(T(task.project+"  ·  "+(String.IsNullOrEmpty(task.due)?"Sans échéance":DateTime.ParseExact(task.due,"yyyy-MM-dd",null).ToString("dd MMM")+(String.IsNullOrEmpty(task.dueTime)?"":" à "+task.dueTime))+(task.repeat!="none"?"  ·  ↻":"")+(task.remindMinutes>=0?"  ·  Rappel":"")+(task.priority=="Haute"?"  ·  Prioritaire":""),10,task.priority=="Haute"?Accent:Muted));row.Children.Add(text);var divider=new Border{BorderBrush=FaintLine,BorderThickness=new Thickness(0,0,0,1),Child=row};list.Children.Add(divider);}return list;}
    StackPanel ProjectList(int limit){return ProjectListV2(limit);}
    void Projects(StackPanel root){ProjectsV2(root);}
    void Services(StackPanel root){var body=new StackPanel();foreach(string s in (store.Value.settings.EnableBotModule?new[]{"Bots et applications","Notifications","Services personnels"}:new[]{"Notifications","Services personnels"}))body.Children.Add(T(s+"   ·   Non connecté",13,Muted,new Thickness(0,10,0,18)));body.Children.Add(T("Les états réels et les alertes apparaîtront après connexion de vos services.",12,Muted));root.Children.Add(Card("Vos connexions",body));}
