    void ModernIcon(WButton button,string url,bool vertical=true){var row=new StackPanel{Orientation=vertical?Orientation.Vertical:Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center};var img=new System.Windows.Controls.Image{Width=21,Height=21,Margin=vertical?new Thickness(0,0,0,6):new Thickness(0,0,7,0)};using(var icon=SiteIcons.Placeholder())img.Source=ToImage(icon);row.Children.Add(img);row.Children.Add(T(Convert.ToString(button.Content),10));button.Content=row;string brand=SiteIcons.Brand(url);if(brand==null)return;using(var bundled=BundledLogos.Get(brand)){if(bundled!=null){img.Source=ToImage(bundled);return;}}System.Threading.ThreadPool.QueueUserWorkItem(delegate{try{var image=SiteIcons.Get(brand);if(image==null||Dispatcher.HasShutdownStarted)return;var source=ToImage(image);Dispatcher.BeginInvoke((Action)delegate{img.Source=source;});}catch{}});}
